import{_ as n,C as o,o as t,c as s,a2 as a,b as c,w as i,a as d,E as l,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const y=JSON.parse('{"title":"14.6 Caching Strategies & Cache Invalidation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.6-caching.md","filePath":"system-design/14.6-caching.md"}'),g={name:"system-design/14.6-caching.md"};function u(m,e,p,C,v,f){const r=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="_14-6-caching-strategies-cache-invalidation" tabindex="-1">14.6 Caching Strategies &amp; Cache Invalidation <a class="header-anchor" href="#_14-6-caching-strategies-cache-invalidation" aria-label="Permalink to &quot;14.6 Caching Strategies &amp; Cache Invalidation&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Caching stores copies of frequently accessed data in high-speed storage (such as in-memory RAM) so subsequent requests are served in microseconds rather than querying slower disk-bound databases or expensive AI APIs.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Browser &amp; CDN Cache</strong>: Static JS/CSS chunks and recipe images cached via HTTP <code>Cache-Control: public, max-age=31536000, immutable</code>.</li><li><strong>Client Application Cache</strong>: TanStack React Query maintains an in-memory query cache in [27-kitchen-companion-pro/src/App.tsx:L42](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/App.tsx#L42) (<code>new QueryClient()</code>), caching recipe lists and user preferences.</li><li><strong>Planned In-Memory Cache</strong>: Redis caching layer for member profiles and common AI substitution queries.</li></ul><hr><h2 id="_3-multi-layer-caching-flow" tabindex="-1">3. Multi-Layer Caching Flow <a class="header-anchor" href="#_3-multi-layer-caching-flow" aria-label="Permalink to &quot;3. Multi-Layer Caching Flow&quot;">​</a></h2>',8)),(t(),c(h,null,{default:i(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20User%5B%22User%20Client%20Browser%22%5D%20--%3E%7C1.%20Check%20Browser%20Cache%7C%20BrowserCache%7B%22Browser%20Cache%20Hit%3F%22%7D%0A%20%20%20%20BrowserCache%20--%3E%7CYes%7C%20FastRender%5B%22Instant%20Render%20(%3C1ms)%22%5D%0A%20%20%20%20BrowserCache%20--%3E%7CNo%7C%20CDNEval%7B%222.%20Edge%20CDN%20Hit%3F%22%7D%0A%20%20%20%20CDNEval%20--%3E%7CYes%7C%20EdgeDelivery%5B%22Edge%20Cache%20(10-25ms)%22%5D%0A%20%20%20%20CDNEval%20--%3E%7CNo%7C%20RedisEval%7B%223.%20Redis%20In-Memory%20Hit%3F%22%7D%0A%20%20%20%20RedisEval%20--%3E%7CYes%7C%20RedisDelivery%5B%22Redis%20Cache%20(2-5ms)%22%5D%0A%20%20%20%20RedisEval%20--%3E%7CNo%7C%20DBOp%5B%224.%20Query%20MongoDB%20%2F%20Call%20Gemini%20AI%22%5D%0A%20%20%20%20DBOp%20--%3E%20WriteBack%5B%22Write%20result%20into%20Redis%20%26%20CDN%22%5D%0A%20%20%20%20WriteBack%20--%3E%20FastRender%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_4-caching-patterns-comparison" tabindex="-1">4. Caching Patterns Comparison <a class="header-anchor" href="#_4-caching-patterns-comparison" aria-label="Permalink to &quot;4. Caching Patterns Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Strategy</th><th>Read Flow</th><th>Write Flow</th><th>Consistency</th><th>Latency</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Cache-Aside (Recommended)</strong></td><td>Read cache; on miss read DB &amp; write cache</td><td>Write directly to DB; invalidate cache</td><td>Eventual consistency</td><td>Low</td><td>Optimal for recipe views &amp; member profiles</td></tr><tr><td><strong>Read-Through</strong></td><td>Client only reads cache; cache auto-loads DB</td><td>Same as above</td><td>Stronger</td><td>Low</td><td>Requires cache provider plugin</td></tr><tr><td><strong>Write-Through</strong></td><td>Client writes to cache; cache writes to DB</td><td>Synchronous dual write</td><td>Strong consistency</td><td>Higher write latency</td><td>Good for critical financial ledgers</td></tr><tr><td><strong>Write-Back (Write-Behind)</strong></td><td>Client writes to cache; cache writes DB async</td><td>Batched async DB writes</td><td>Risk of data loss on crash</td><td>Ultra-low write latency</td><td>Good for high-frequency kitchen scale logs</td></tr><tr><td><strong>Write-Around</strong></td><td>Client writes direct to DB bypassing cache</td><td>Does not touch cache on write</td><td>Prevents cache pollution</td><td>Higher read latency on first load</td><td>Good for raw safety logs</td></tr></tbody></table><hr><h2 id="_5-cache-eviction-invalidation-policies" tabindex="-1">5. Cache Eviction &amp; Invalidation Policies <a class="header-anchor" href="#_5-cache-eviction-invalidation-policies" aria-label="Permalink to &quot;5. Cache Eviction &amp; Invalidation Policies&quot;">​</a></h2><ol><li><strong>Eviction Policy</strong>: <strong>LRU (Least Recently Used)</strong> in Redis ensures that recipes viewed weeks ago are naturally evicted to make room for trending viral reels.</li><li><strong>TTL (Time to Live)</strong>: <ul><li>User Profiles: 15-minute TTL. Invalidate immediately on profile edit (<code>updateProfile()</code>).</li><li>AI Substitution Cache: 7-day TTL (culinary science substitutions rarely change).</li></ul></li><li><strong>Thundering Herd / Cache Stampede Defense</strong>: When a cached viral recipe expires, use <strong>Mutex Locking</strong> (<code>SET recipe:butter-chicken:lock true EX 5 NX</code>) so only one request queries MongoDB while other concurrent requests wait or serve stale data.</li></ol><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Stale profile data if a user updates their dark mode preference but the client serves the cached profile.</li><li><strong>At 100x</strong>: Redis memory exhaustion if large video reel manifests are stored without compression.</li><li><strong>At 1,000x</strong>: Cache stampede: hundreds of thousands of concurrent users browsing a viral Christmas turkey recipe when its cache key expires, crashing the primary MongoDB replica.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Implement <strong>Probabilistic Early Expiration (XFetch algorithm)</strong> in Redis: recompute and refresh the cache key in the background slightly before the TTL expires based on request frequency, ensuring zero cache stampede spikes.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;In Cooking Nexus, we use a multi-tier caching hierarchy: HTTP edge caching for static recipe media, TanStack Query for client-side state, and a Cache-Aside Redis layer for member profiles and common AI substitution prompts. To protect our primary database from cache stampedes when viral cooking reels expire, we combine a 15-minute TTL with mutex locking, ensuring only one worker queries MongoDB while other concurrent requests receive stale-while-revalidate data.&quot;</p>',15))])}const k=n(g,[["render",u]]);export{y as __pageData,k as default};
